result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_grader.py", "content": "import pytest

from grader import grade


# ---------------------------------------------------------------------------
# (a) multiple_choice
# ---------------------------------------------------------------------------

class TestMultipleChoice:
    def test_exact_match(self):
        assert grade({"type": "multiple_choice", "correct": "B"}, "B") == 1.0

    def test_case_insensitive(self):
        assert grade({"type": "multiple_choice", "correct": "B"}, "b") == 1.0
        assert grade({"type": "multiple_choice", "correct": "b"}, "B") == 1.0

    def test_whitespace_stripped(self):
        assert grade({"type": "multiple_choice", "correct": "C"}, "  C ") == 1.0
        assert grade({"type": "multiple_choice", "correct": " C "}, "C") == 1.0

    def test_case_and_whitespace_combined(self):
        assert grade({"type": "multiple_choice", "correct": "A"}, "\ta\n") == 1.0

    def test_wrong_letter(self):
        assert grade({"type": "multiple_choice", "correct": "B"}, "D") == 0.0

    def test_empty_string_scores_zero(self):
        assert grade({"type": "multiple_choice", "correct": "B"}, "") == 0.0


# ---------------------------------------------------------------------------
# (b) numeric
# ---------------------------------------------------------------------------

class TestNumericParsing:
    SPEC = {"type": "numeric", "correct": 4500}

    def test_plain_integer(self):
        assert grade(self.SPEC, "4500") == 1.0

    def test_surrounding_whitespace(self):
        assert grade(self.SPEC, " 4.50 ") == 0.0  # wrong value parses fine
        assert grade({"type": "numeric", "correct": 4.5}, " 4.50 ") == 1.0

    def test_thousands_separators(self):
        assert grade(self.SPEC, "4,500") == 1.0
        assert grade(self.SPEC, " 4,500 ") == 1.0
        assert grade({"type": "numeric", "correct": 1234567}, "1,234,567") == 1.0

    def test_malformed_thousands_separators_do_not_parse(self):
        assert grade({"type": "numeric", "correct": 1.5}, "1,5") == 0.0
        assert grade({"type": "numeric", "correct": 4500}, "45,00") == 0.0

    def test_scientific_notation(self):
        assert grade(self.SPEC, "4.5e3") == 1.0
        assert grade(self.SPEC, "4.5E3") == 1.0
        assert grade({"type": "numeric", "correct": 0.0045}, "4.5e-3") == 1.0

    def test_non_parseable_scores_zero_without_raising(self):
        for bad in ["abc", "", "4.5.6", "--3", "four"]:
            assert grade({"type": "numeric", "correct": 42}, bad) == 0.0

    def test_empty_string_scores_zero(self):
        assert grade({"type": "numeric", "correct": 42}, "") == 0.0


class TestNumericTolerances:
    def test_default_tolerances_are_zero(self):
        spec = {"type": "numeric", "correct": 100}
        assert grade(spec, "100") == 1.0
        assert grade(spec, "100.000001") == 0.0

    def test_atol_accepts_within(self):
        spec = {"type": "numeric", "correct": 100, "atol": 0.5}
        assert grade(spec, "100.4") == 1.0

    def test_atol_rejects_outside(self):
        spec = {"type": "numeric", "correct": 100, "atol": 0.5}
        assert grade(spec, "100.6") == 0.0

    def test_atol_exactly_at_boundary_accepted(self):
        spec = {"type": "numeric", "correct": 100, "atol": 1}
        assert grade(spec, "99") == 1.0   # |99 - 100| == 1 == atol
        assert grade(spec, "101") == 1.0  # |101 - 100| == 1 == atol

    def test_just_beyond_atol_boundary_rejected(self):
        spec = {"type": "numeric", "correct": 100, "atol": 1}
        assert grade(spec, "98.9") == 0.0

    def test_rtol_accepts_within(self):
        spec = {"type": "numeric", "correct": 200, "rtol": 0.01}  # +/- 2
        assert grade(spec, "198.5") == 1.0

    def test_rtol_rejects_outside(self):
        spec = {"type": "numeric", "correct": 200, "rtol": 0.01}
        assert grade(spec, "202.1") == 0.0

    def test_rtol_exactly_at_boundary_accepted(self):
        spec = {"type": "numeric", "correct": 200, "rtol": 0.01}
        assert grade(spec, "198") == 1.0  # 2 <= 0.01 * 200
        assert grade(spec, "202") == 1.0

    def test_atol_and_rtol_combined_either_passes(self):
        spec = {"type": "numeric", "correct": 1000, "atol": 0.5, "rtol": 0.01}
        assert grade(spec, "1000.2") == 1.0  # within atol
        assert grade(spec, "990") == 1.0     # within rtol, far outside atol
        assert grade(spec, "985") == 0.0     # outside both

    def test_missing_fields_mean_zero_tolerance(self):
        spec = {"type": "numeric", "correct": 7}
        assert grade(spec, "7") == 1.0
        assert grade(spec, "7.0001") == 0.0

    def test_negative_correct_value_with_rtol(self):
        spec = {"type": "numeric", "correct": -200, "rtol": 0.01}
        assert grade(spec, "-198") == 1.0
        assert grade(spec, "-197") == 0.0


# ---------------------------------------------------------------------------
# (c) short_answer
# ---------------------------------------------------------------------------

class TestShortAnswer:
    SPEC = {"type": "short_answer", "accepted": ["Paris"]}

    def test_case_insensitive(self):
        assert grade(self.SPEC, "PARIS") == 1.0
        assert grade(self.SPEC, "pArIs") == 1.0

    def test_internal_whitespace_collapsed(self):
        spec = {"type": "short_answer", "accepted": ["new york city"]}
        assert grade(spec, "new   york\tcity") == 1.0
        assert grade(spec, " new york city ") == 1.0

    def test_punctuation_stripped(self):
        assert grade(self.SPEC, "Paris.") == 1.0
        assert grade(self.SPEC, "'Paris?!'") == 1.0
        assert grade(self.SPEC, 'Paris;:') == 1.0
        assert grade(self.SPEC, '"Paris,"') == 1.0

    def test_matches_any_accepted_string(self):
        spec = {"type": "short_answer", "accepted": ["Paris", "City of Light"]}
        assert grade(spec, "city of light!") == 1.0

    def test_wrong_answer_scores_zero(self):
        assert grade(self.SPEC, "London") == 0.0

    def test_empty_string_scores_zero_unless_accepted(self):
        assert grade(self.SPEC, "") == 0.0
        assert grade({"type": "short_answer", "accepted": [""]}, "") == 1.0


# ---------------------------------------------------------------------------
# dispatch / API behaviour
# ---------------------------------------------------------------------------

class TestGradeAPI:
    def test_returns_floats_one_or_zero_only(self):
        specs = [
            {"type": "multiple_choice", "correct": "A"},
            {"type": "numeric", "correct": 1},
            {"type": "short_answer", "accepted": ["x"]},
        ]
        for spec in specs:
            for ans in ["A", "z", "", "??"]:
                result = grade(spec, ans)
                assert result in (0.0, 1.0)
                assert isinstance(result, float)

    def test_unknown_type_raises(self):
        with pytest.raises(ValueError):
            grade({"type": "essay"}, "whatever")
"})
